match
$e isa fincen_entity, has name $name;
$f isa filing;
originator (filing: $f, originating_entity: $e);
benefits (filing: $f, beneficiary: $e);
reduce $num_filings = count($f) groupby $e, $name;
sort $num_filings desc;
limit 5;
fetch {
  "entity_name": $name,
  "num_filings": $num_filings
};

