with fun filing_count($e: fincen_entity) -> integer:
  match
    filed (filer: $e, filing: $f);
  return count;
with fun total_filing_amount($e: fincen_entity) -> integer:
  match
    filed (filer: $e, filing: $f);
    $f has amount $a;
  return sum($a);
